package com.vynedam.stockai.security;
import com.vynedam.stockai.model.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final long expirySeconds; public JwtService(@Value("${app.jwt-secret}") String secret,@Value("${app.jwt-expiry-seconds:28800}") long expiry){if(secret.length()<32)throw new IllegalStateException("JWT_SECRET must be at least 32 characters");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));expirySeconds=expiry;} public String issue(User u){var now=Instant.now();return Jwts.builder().subject(u.id).claim("role",u.role.name()).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(expirySeconds))).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
